interface.definition:
a!localVariables(
  local!pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: - 1,
    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "askId", ascending: false)
  ),
  local!pagingInfoCoreAsk:#"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: - 1,
    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "version", ascending: false)
  ),
  local!rotationalPagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
    startIndex: 1,
    batchSize: - 1,
    sort: {
      #"SYSTEM_SYSRULES_sortInfo"(field: "askId", ascending: false),
      #"SYSTEM_SYSRULES_sortInfo"(field: "version", ascending: false)
    }
  ),
  local!rotationalColumns,
  local!columns,
  local!selectedTab: 1,
  local!selectedTaskIds,
  local!selectedRotationalTaskIds,
  local!coreAsks: a!refreshVariable(
    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3235974"(
      columns: local!columns,
      pagingInfo: local!pagingInfoCoreAsk,
      returnCDT: true,
      isActive: true()
    ),
    refreshAlways: true,
    refreshInterval: 0.5
  ),
  local!getDistinctCoreASKs: #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(index(local!coreAsks, "askId", null)),
  local!filteredAsks: #"SYSTEM_SYSRULES_forEach"(
    items: local!getDistinctCoreASKs,
    expression: index(
      local!coreAsks,
      wherecontains(
        fv!item,
        index(local!coreAsks, "askId", null)
      )[1],
      null
    ),

  ),
  local!askDetailIds:index(local!filteredAsks,"askDetailId",null),
  local!rotationalAsks: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3338676"(
    columns: local!rotationalColumns,
    pagingInfo: local!rotationalPagingInfo,
    returnCDT: true,
    isActive: true()
  ),
  #"SYSTEM_SYSRULES_headerContentLayout"(
    header: #"SYSTEM_SYSRULES_billboardLayout_v1"(
      backgroundColor: "#0b5394",
      /*backgroundMedia: a!documentImage(*/
      /*document: cons!CAW_DOC_BILLBOARD*/
      /*),*/
      height: "EXTRA_SHORT",
      overlay: #"SYSTEM_SYSRULES_fullOverlay"(
        alignVertical: "MIDDLE",
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  labelPosition: "COLLAPSED",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "ASK",
                    color: "#FFFFFF",
                    size: "LARGE",
                    style: "STRONG"
                  )
                )
              )
            }
          )
        },
        style: "NONE"
      )
    ),
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_cardLayout"(
              contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "list-alt",
                    color: if(
                      local!selectedTab = 1,
                      "STANDARD",
                      "SECONDARY"
                    ),
                    size: "MEDIUM"
                  ),
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: " " & #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3371522",
                    color: "ACCENT",
                    size: "MEDIUM",
                    style: if(local!selectedTab = 1, "STRONG", "PLAIN")
                  )
                },
                align: "CENTER"
              ),
              link: #"SYSTEM_SYSRULES_dynamicLink"(value: 1, saveInto: local!selectedTab),
              style: if(local!selectedTab = 1, "ACCENT", "NONE"),
              showBorder: true
            )
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_cardLayout"(
              contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "list-alt",
                    color: if(
                      local!selectedTab = 2,
                      "STANDARD",
                      "SECONDARY"
                    ),
                    size: "MEDIUM"
                  ),
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: " " & #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3371544",
                    color: "ACCENT",
                    size: "MEDIUM",
                    style: if(local!selectedTab = 2, "STRONG", "PLAIN")
                  )
                },
                align: "CENTER"
              ),
              link: #"SYSTEM_SYSRULES_dynamicLink"(value: 2, saveInto: local!selectedTab),
              style: if(local!selectedTab = 2, "ACCENT", "NONE"),
              showBorder: true
            )
          ),
          #"SYSTEM_SYSRULES_columnLayout"(),
          #"SYSTEM_SYSRULES_columnLayout"(),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  labelPosition: "COLLAPSED",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "plus",
                      linkStyle: "STANDALONE",
                      color: "ACCENT",
                      size: "MEDIUM"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "   Create New ASK",
                      linkStyle: "STANDALONE",
                      size: "MEDIUM",
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                )
              },
              link: #"SYSTEM_SYSRULES_startProcessLink"(processModel: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3191060"),
              height: "AUTO",
              showWhen: isusermemberofgroups(
                loggedInUser(),
                {
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3176497",
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177108",
                  /*replacement grp for DPP Chief of Staff*/
                  #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11723973",
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922",

                }
              ),
              style: "INFO",
              marginBelow: "STANDARD"
            ),
            width: "NARROW"
          )
        }
      ),
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: if(
              local!selectedTab = 1,
              #"SYSTEM_SYSRULES_boxLayout"(
                label: "Core ASK List",
                contents: {
                  if(
                    isusermemberofgroups(
                      loggedInUser(),
                      { #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3443785" }
                    ),
                    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3271739"(
                      coreAsks: local!filteredAsks,
                      selectedTaskIds: local!selectedTaskIds
                    ),
                    #"SYSTEM_SYSRULES_textField"(
                      value: "You do not have permission to view this page.",
                      readOnly: true
                    )
                  )
                },
                style: "STANDARD",
                marginBelow: "STANDARD"
              ),
              #"SYSTEM_SYSRULES_boxLayout"(
                label: "Rotational ASK List",
                contents: {
                  if(
                    isusermemberofgroups(
                      loggedInUser(),
                      { #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3443785" }
                    ),
                    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3338413"(
                      selectedRotationalTaskIds: local!selectedRotationalTaskIds,
                      rotationalAsks: local!rotationalAsks
                    ),
                    #"SYSTEM_SYSRULES_textField"(
                      value: "You do not have permission to view this page.",
                      readOnly: true
                    )
                  )
                },
                style: "STANDARD",
                marginBelow: "STANDARD"
              )
            )
          )
        }
      )
    }
  )
)
